import java.util.*;
import java.io.*;

public class Main {
    static final long Mod1 = 998244353;
    static final long Mod2 = 1000000007;
    static long ans = 0;
    static long n;
    static long Cnt1 = 0;
    static long[] sum = new long[7];
    static List<Long>[] val = new ArrayList[7];
    static long Cnt2 = 0;
    static long[] Tpow = {1, 10, 100, 1000, 10000, 100000, 1000000};

    static {
        for (int i = 0; i < 7; i++) {
            val[i] = new ArrayList<>();
        }
    }

    static int ReadLong(BufferedReader br, StringTokenizer st) throws IOException {
        while (!st.hasMoreTokens()) {
            st = new StringTokenizer(br.readLine());
        }
        return Integer.parseInt(st.nextToken());
    }

    static void DFS1(int A, long B) {
        if (A == 7) return;
        long valA = (Cnt1 - B + Mod1) % Mod1;
        val[A].add(valA);
        sum[A] += valA;
        Cnt1++;
        for (int i = 0; i <= 9; i++) {
            DFS1(A + 1, B * 10 + i);
        }
    }

    static boolean check(long x) {
        final long Cut = 1000000;
        return x * Cut + 999999 <= n && x * Cut * 10 > n;
    }

    static void DFS2(int A, long B) {
        if (B > n) return;
        if (check(B)) {
            for (int i = 0; i <= 6; i++) {
                long cur = ((Cnt2 + 1 - B * Tpow[i]) % Mod1 + Mod1) % Mod1;
                List<Long> listVal = val[i];
                int pos = lowerBound(listVal, Mod1 - cur);
                long size = listVal.size();
                long sumVal = sum[i];
                long contribution = (sumVal + cur * size - Mod1 * (size - pos)) % Mod2;
                ans = (ans + contribution) % Mod2;
            }
            Cnt2 += Cnt1;
        } else {
            Cnt2++;
            ans = (ans + ((Cnt2 - B) % Mod1 + Mod1) % Mod1) % Mod2;
            for (int i = (A == 0) ? 0 : 0; i <= 9; i++) {
                DFS2(A + 1, B * 10 + i);
            }
        }
    }

    static int lowerBound(List<Long> list, long target) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= target) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Long.parseLong(st.nextToken());
        DFS1(0, 0);
        for (int i = 0; i <= 6; i++) {
            Collections.sort(val[i]);
        }
        Cnt2 = -1;
        DFS2(0, 0);
        System.out.println(ans);
    }
}
